head.script:
scwin.onpageload = function() {
    // 기본적으로 세부사항 선택 상태로 설정
    scwin.changeSelectedMenu("detail");
};

// 세부사항 메뉴 클릭 이벤트
scwin.menu_detail_onclick = function(e) {
    console.log("=== 세부사항 메뉴 클릭 ===");
    scwin.changeSelectedMenu("detail");
    // 부모 창의 메뉴 변경 함수 호출
    scwin.callParentMenuChange("projectSettingDetail");
};

// 액세스 메뉴 클릭 이벤트
scwin.menu_access_onclick = function(e) {
    console.log("=== 액세스 메뉴 클릭 ===");
    scwin.changeSelectedMenu("access");
    // 부모 창의 메뉴 변경 함수 호출
    scwin.callParentMenuChange("projectSettingAccess");
};

// GitHub 연동 메뉴 클릭 이벤트
scwin.menu_github_onclick = function(e) {
    console.log("=== GitHub 연동 메뉴 클릭 ===");
    scwin.changeSelectedMenu("github");
    // 부모 창의 메뉴 변경 함수 호출
    scwin.callParentMenuChange("projectSettingGithub");
};

// 부모 창의 메뉴 변경 함수 호출
scwin.callParentMenuChange = function(menuType) {
    try {
        // WebSquare에서는 $p.parent()를 사용하여 부모 프레임에 접근
        var parentFrame = $p.parent();

        if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출:", menuType, "($p.parent)");
            parentFrame.scwin.changeMenu(menuType);
        } else if (parent && parent.scwin && parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출:", menuType, "(parent)");
            parent.scwin.changeMenu(menuType);
        } else if (window.parent && window.parent.scwin && window.parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출:", menuType, "(window.parent)");
            window.parent.scwin.changeMenu(menuType);
        } else {
            console.error("부모 창의 changeMenu 함수를 찾을 수 없습니다.");
        }
    } catch(e) {
        console.error("부모 창 메뉴 변경 오류:", e);
    }
};

// 선택된 메뉴 스타일 변경
scwin.changeSelectedMenu = function(selectedMenu) {
    try {
        console.log("설정 메뉴 선택 변경 시작:", selectedMenu);

        // 모든 메뉴에서 selected-setting-menu 클래스 제거
        grp_detail.removeClass("selected-setting-menu");
        grp_access.removeClass("selected-setting-menu");
        grp_github.removeClass("selected-setting-menu");

        // 모든 선택 표시 바 숨기기
        grp_activeBar_detail.hide();
        grp_activeBar_access.hide();
        grp_activeBar_github.hide();

        // 모든 메뉴의 배경색을 투명하게 강제 설정
        grp_detail.setStyle("background-color", "transparent");
        grp_access.setStyle("background-color", "transparent");
        grp_github.setStyle("background-color", "transparent");

        // 선택된 메뉴에만 스타일 적용
        switch(selectedMenu) {
            case "detail":
                grp_detail.addClass("selected-setting-menu");
                grp_detail.setStyle("background-color", "rgba(255,184,35,0.2)");
                grp_activeBar_detail.show();
                break;
            case "access":
                grp_access.addClass("selected-setting-menu");
                grp_access.setStyle("background-color", "rgba(255,184,35,0.2)");
                grp_activeBar_access.show();
                break;
            case "github":
                grp_github.addClass("selected-setting-menu");
                grp_github.setStyle("background-color", "rgba(255,184,35,0.2)");
                grp_activeBar_github.show();
                break;
        }

        console.log("설정 메뉴 선택 완료:", selectedMenu);

        // 데이터맵에도 선택된 메뉴 저장
        dm_settingSideMenu.set("selectedMenu", selectedMenu);
    } catch(e) {
        console.log("설정 메뉴 스타일 변경 오류:", e);
    }
};

// 부모에서 호출할 수 있는 메뉴 업데이트 함수
scwin.updateSelectedMenu = function(menuType) {
    scwin.changeSelectedMenu(menuType);
};

// 프로젝트명 업데이트 함수
scwin.updateProjectName = function(projectName) {
    if (projectName) {
        dm_settingSideMenu.set("projectName", projectName);
    }
};
